{"implementation": "def solve(case):
    segments = case["segments"]
    budget = case["budget"]

    # Validate required fields
    for seg in segments:
        for field in ("name", "importance", "minimum", "capacity"):
            if field not in seg:
                raise ValueError(f"Segment missing required field: {field}")

    quota_sum = sum(seg["minimum"] for seg in segments)
    total_capacity = sum(seg["capacity"] for seg in segments)

    if budget < quota_sum or budget > total_capacity:
        raise ValueError(
            f"Budget {budget} is outside valid range [{quota_sum}, {total_capacity}]"
        )

    # Initialize every segment at its minimum quota (no mutation of case)
    allocs = [seg["minimum"] for seg in segments]
    remaining = budget - quota_sum

    # Greedy: each round give one token to the segment with highest importance/(alloc+1)
    # Tie-break by original segment order (earlier index wins)
    while remaining > 0:
        best_idx = -1
        best_priority = -1.0
        for i, seg in enumerate(segments):
            if allocs[i] >= seg["capacity"]:
                continue
            priority = seg["importance"] / (allocs[i] + 1)
            if priority > best_priority:
                best_priority = priority
                best_idx = i
        if best_idx == -1:
            break  # all segments are at capacity
        allocs[best_idx] += 1
        remaining -= 1

    by_name = {seg["name"]: allocs[i] for i, seg in enumerate(segments)}

    return {
        "allocations": allocs,
        "by_name": by_name,
        "total": sum(allocs),
    }
"}
